use std::fs

fn find(names: Vec<string>, key: string) -> int {
    let mut i = 0
    while i < names.len() {
        if names[i] == key {
            return i as int
        }
        i += 1
    }
    -1
}

fn main() {
    let text = fs::read_to_string("/dev/stdin") ?? ""
    let mut names: Vec<string> = Vec::new()
    let mut bals: Vec<int> = Vec::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "open" && parts.len() >= 3 {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if find(names, parts[1]) >= 0 {
                println("error: duplicate account")
            } else {
                names.push(parts[1])
                bals.push(amt)
                println("ok")
            }
        } else if cmd == "balance" && parts.len() >= 2 {
            let i = find(names, parts[1])
            if i >= 0 {
                println("${bals[i as usize]}")
            } else {
                println("error: unknown account ${parts[1]}")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && parts.len() >= 3 {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            let i = find(names, parts[1])
            if amt <= 0 {
                println("error: invalid amount")
            } else if i < 0 {
                println("error: unknown account ${parts[1]}")
            } else {
                let k = i as usize
                if cmd == "deposit" {
                    bals[k] = bals[k] + amt
                    println("ok")
                } else if bals[k] < amt {
                    println("error: insufficient funds")
                } else {
                    bals[k] = bals[k] - amt
                    println("ok")
                }
            }
        } else if cmd == "transfer" && parts.len() >= 4 {
            let amt: int = parts[3].parse::<int>().unwrap_or(0)
            let i = find(names, parts[1])
            let j = find(names, parts[2])
            if amt <= 0 {
                println("error: invalid amount")
            } else if i < 0 {
                println("error: unknown account ${parts[1]}")
            } else if j < 0 {
                println("error: unknown account ${parts[2]}")
            } else if i == j {
                println("error: same account")
            } else {
                let a = i as usize
                let b = j as usize
                if bals[a] < amt {
                    println("error: insufficient funds")
                } else {
                    bals[a] = bals[a] - amt
                    bals[b] = bals[b] + amt
                    println("ok")
                }
            }
        }
    }
    // selection order by name
    let n = names.len()
    let mut used: Vec<bool> = Vec::new()
    let mut c = 0
    while c < n {
        used.push(false)
        c += 1
    }
    let mut done = 0
    while done < n {
        let mut best: int = -1
        let mut k = 0
        while k < n {
            if !used[k] {
                if best < 0 || names[k] < names[best as usize] {
                    best = k as int
                }
            }
            k += 1
        }
        let bi = best as usize
        used[bi] = true
        println("${names[bi]} ${bals[bi]}")
        done += 1
    }
}

